import type { CurrencyRules } from "./currency-rules";
import data from "./currencies.json";
import { normalizeSearchText } from "./search-text";

// The app's currency list (R1, R71), generated by scripts/generate-currencies.mjs.

export type LocalizedName = { vi: string; en: string };

export type CurrencyInfo = CurrencyRules & {
  symbol: string;
  /** Short symbol for amounts, e.g. `$` for SGD (R1). */
  narrowSymbol: string;
  name: LocalizedName;
  /** ISO 3166-1 codes of the countries where it is legal tender. */
  countries: string[];
};

const CURRENCIES: readonly CurrencyInfo[] = data.currencies;
const BY_CODE = new Map(
  CURRENCIES.map((currency) => [currency.code, currency]),
);
const COUNTRY_NAMES: Record<string, LocalizedName> = data.countries;
const REGION_CURRENCY: Record<string, string> = data.regionCurrency;
const POPULAR: readonly string[] = data.popular;

/** A currency that can be picked for a new plan or a settings change. */
export function findCurrency(code: string): CurrencyInfo | undefined {
  return BY_CODE.get(code.toUpperCase());
}

export function isSelectableCurrency(code: string): boolean {
  return BY_CODE.has(code.toUpperCase());
}

export function countryName(region: string): LocalizedName | undefined {
  return COUNTRY_NAMES[region];
}

/**
 * Money rules for a plan's currency. Currencies later dropped from the list still work for the
 * plans that use them (R72): their decimals come from Intl and they round like R19's defaults.
 */
export function getCurrencyRules(code: string): CurrencyRules {
  const listed = findCurrency(code);
  if (listed)
    return {
      code: listed.code,
      minorUnits: listed.minorUnits,
      roundingStep: listed.roundingStep,
    };
  const upper = code.toUpperCase();
  if (!/^[A-Z]{3}$/.test(upper))
    throw new RangeError(`Not a currency code: ${code}`);
  const minorUnits =
    new Intl.NumberFormat("en", {
      style: "currency",
      currency: upper,
    }).resolvedOptions().maximumFractionDigits ?? 2;
  return {
    code: upper,
    minorUnits,
    roundingStep: minorUnits > 0 ? "0.5" : "1",
  };
}

// ---------------------------------------------------------------------------
// Search (R71): code, names in Vietnamese and English, country names, symbol; accent-free (R34).
// ---------------------------------------------------------------------------

type SearchEntry = {
  currency: CurrencyInfo;
  texts: string[];
  symbols: string[];
};

const SEARCH_INDEX: readonly SearchEntry[] = CURRENCIES.map((currency) => ({
  currency,
  texts: [
    currency.name.vi,
    currency.name.en,
    ...currency.countries.flatMap((region) => {
      const names = COUNTRY_NAMES[region];
      return names ? [names.vi, names.en] : [];
    }),
  ].map(normalizeSearchText),
  symbols: [currency.symbol, currency.narrowSymbol].map((symbol) =>
    symbol.toLowerCase(),
  ),
}));

/** Lower is better; `undefined` means no match. */
function matchScore(
  entry: SearchEntry,
  query: string,
  rawQuery: string,
): number | undefined {
  const code = entry.currency.code.toLowerCase();
  if (code === query) return 0;
  if (entry.symbols.includes(rawQuery)) return 1;
  let best: number | undefined;
  const consider = (score: number) => {
    if (best === undefined || score < best) best = score;
  };
  if (code.startsWith(query)) consider(2);
  for (const text of entry.texts) {
    if (text.startsWith(query)) consider(3);
    else if (text.includes(` ${query}`)) consider(4);
    else if (text.includes(query)) consider(5);
  }
  return best;
}

function popularRank(code: string): number {
  const index = POPULAR.indexOf(code);
  return index === -1 ? POPULAR.length : index;
}

/** Currencies matching the picker's search box, best first: exact code, symbol, then name and country matches. */
export function searchCurrencies(query: string): CurrencyInfo[] {
  const normalized = normalizeSearchText(query);
  if (!normalized) return [];
  const rawQuery = query.trim().toLowerCase();
  return SEARCH_INDEX.flatMap((entry) => {
    const score = matchScore(entry, normalized, rawQuery);
    return score === undefined ? [] : [{ currency: entry.currency, score }];
  })
    .sort(
      (a, b) =>
        a.score - b.score ||
        popularRank(a.currency.code) - popularRank(b.currency.code) ||
        a.currency.code.localeCompare(b.currency.code),
    )
    .map((match) => match.currency);
}

export type CurrencyPickerSections = {
  /** Currencies of the account's recent plans, most recent first ("Bạn đã dùng gần đây"). */
  recent: CurrencyInfo[];
  /** The popular group, minus the ones already in `recent` ("Phổ biến"). */
  popular: CurrencyInfo[];
  /** Every currency, A–Z by code. */
  all: CurrencyInfo[];
};

/** What the picker shows before anything is typed (R71). */
export function currencyPickerSections(
  recentCodes: readonly string[],
): CurrencyPickerSections {
  const recent = [
    ...new Set(recentCodes.map((code) => code.toUpperCase())),
  ].flatMap((code) => {
    const currency = BY_CODE.get(code);
    return currency ? [currency] : [];
  });
  const shown = new Set(recent.map((currency) => currency.code));
  const popular = POPULAR.filter((code) => !shown.has(code)).flatMap((code) => {
    const currency = BY_CODE.get(code);
    return currency ? [currency] : [];
  });
  return { recent, popular, all: [...CURRENCIES] };
}

// ---------------------------------------------------------------------------
// Default currency for a new plan (R70).
// ---------------------------------------------------------------------------

/** Region of a browser locale such as `vi-VN` or `en-SG`; `null` when the locale has none (`vi`). */
export function regionOfLocale(locale: string): string | null {
  try {
    return new Intl.Locale(locale).region ?? null;
  } catch {
    return null;
  }
}

export type DefaultCurrencyInput = {
  /** Currency of the most recent plan the owner created. */
  lastPlanCurrency?: string | null;
  /** Region from the browser's language settings, e.g. `VN` from `vi-VN`. */
  browserRegion?: string | null;
  /** The app's current language. */
  language: string;
};

/** Last plan's currency, then the browser region's currency, then the language: Vietnamese → VND, else USD (R70). */
export function defaultCurrency({
  lastPlanCurrency,
  browserRegion,
  language,
}: DefaultCurrencyInput): string {
  if (lastPlanCurrency && isSelectableCurrency(lastPlanCurrency))
    return lastPlanCurrency.toUpperCase();
  const regional = browserRegion
    ? REGION_CURRENCY[browserRegion.toUpperCase()]
    : undefined;
  if (regional && isSelectableCurrency(regional)) return regional;
  return language.toLowerCase().startsWith("vi") ? "VND" : "USD";
}
